"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/team/variants/01-panels";
import View1 from "./components/team/variants/02-spotlight";
import View2 from "./components/team/variants/03-grid";
import View3 from "./components/team/variants/04-marquee";
const variants = {"panels":View0,"spotlight":View1,"grid":View2,"marquee":View3};
export interface ArtemisTeamProps { className?: string; variant?: "panels" | "spotlight" | "grid" | "marquee"; }
export function ArtemisTeam({ className, variant = "panels" }: ArtemisTeamProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
